import itertools

def is_prime(n):
    """Checks if a number n is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_good_triples(limit=50):
    """
    Generates the first 'limit' good triples based on the (p, 1, 1) structure.
    """
    good_triples = []
    triple_count = 0
    p = 2  # Start with the first prime

    while triple_count < limit:
        if is_prime(p):
            # Permutations of (p, 1, 1)
            permutations = list(set(itertools.permutations([p, 1, 1])))

            for triple in permutations:
                if triple_count < limit:
                    x, y, z = triple
                    S = x**2 + y**2 + z**2
                    good_triples.append({
                        'triple': triple,
                        'S': S
                    })
                    triple_count += 1

        p += 1

    # The triples generated are inherently ordered by p, which means they are ordered by S = p^2 + 2.
    # We verify the order by sorting explicitly, although it should be correct based on generation order.
    good_triples.sort(key=lambda t: t['S'])

    return good_triples

